@Injectable()
export class OrdersService {
  constructor(
    @InjectDrizzle() private readonly db: Database,
    private readonly webhooks: Webhooks<Transaction>,
  ) {}

  async cancelOrder(id: string, reason: string): Promise<Order> {
    const order = await this.db.transaction(async (tx) => {
      await tx.update(orders).set({ status: 'cancelled' }).where(eq(orders.id, id));
      await this.webhooks.dispatch(tx, {
        type: 'order.cancelled',
        tenant: 'northside',
        data: { orderId: id, reason },
      });
      return { id, status: 'cancelled' as const };
    });

    this.webhooks.notify();
    return order;
  }
}

@Controller('webhooks/payments')
export class PaymentWebhooksController {
  constructor(
    @InjectDrizzle() private readonly db: Database,
    private readonly ordersService: OrdersService,
  ) {}

  @Post()
  @HttpCode(HttpStatus.OK)
  @VerifyWebhook('payments')
  async receive(@IncomingWebhook() webhook: IncomingWebhook<PaymentEvent>) {
    const { data } = webhook.payload;

    await this.db.transaction(async (tx) =>
      webhook.processInTransaction(tx, () =>
        this.ordersService.markPaid(tx, data.orderId, data.paymentId),
      ),
    );
  }
}
